-- The Mesh Separator (ADR 0232): a piece of a model (a Model Hotloader character, or a vanilla prop, ragdoll or
-- NPC) becomes a static prop of its own in the Hotloader's props library, with physics generated by the import
-- worker. This file holds what both realms share: the server's switch, what the tool can take pieces from, and who
-- may take them.
mmdhl.separator=mmdhl.separator or {}
local S=mmdhl.separator
local L=mmdhl.L
S.Enabled=CreateConVar('mmdhl_separator_enabled','1',{FCVAR_ARCHIVE,FCVAR_REPLICATED,FCVAR_NOTIFY},'Model Hotloader: 1 lets players use the Mesh Separator tool on this server, 0 switches it off for everyone',0,1)
-- The largest piece the worker is asked to build, in triangles.
S.MaxTriangles=400000
-- How far from the player a piece may appear where it was (the tool's reach, as for placing props).
S.Reach=4096
if SERVER then for _,name in ipairs({'mmdhl_separator_target','mmdhl_separator_place','mmdhl_separator_result'}) do util.AddNetworkString(name) end end
-- What the tool can take a piece of: 'character' (drawn by the Hotloader's native module), 'model' (a prop, a
-- ragdoll, an NPC or a NextBot with a studio model), or nil (a player, the world, a brush entity, a Hotloader
-- static prop, hands and view models).
function S.Kind(ent)
 if not IsValid(ent) or ent:IsWorld() or ent:IsPlayer() then return nil end
 local class=ent:GetClass()
 if class=='mmdhl_prop' or class=='gmod_hands' or class=='viewmodel' or class=='mmdhl_attach_link' then return nil end
 if CLIENT and mmdhl.GetInstance and (tonumber(mmdhl.GetInstance(ent)) or 0)~=0 then return 'character' end
 if class=='mmdhl_ragdoll' then return 'character' end
 local model=ent:GetModel()
 if not isstring(model) or model=='' or model:sub(1,1)=='*' or not model:lower():find('%.mdl$') then return nil end
 if ent:IsNPC() or (ent.IsNextBot and ent:IsNextBot()) or class:find('^prop_') then return 'model' end
 return nil
end
-- Who may take a piece: anyone in single-player; on a server, the owner of the model (prop protection's owner, or
-- the player who spawned it) and administrators; nobody while the server has switched the tool off.
function S.MayUse(p,ent)
 if not S.Enabled:GetBool() then return false,L'separator.error.disabled' end
 if not S.Kind(ent) then return false,L'separator.error.target' end
 if game.SinglePlayer() or (IsValid(p) and p:IsAdmin()) then return true end
 local owner=ent.CPPIGetOwner and ent:CPPIGetOwner() or ent:GetCreator()
 if not IsValid(owner) or owner~=p then return false,L'separator.error.not_owner' end
 return true
end
